using System;
using System.IO;
using System.Diagnostics;
using System.Collections.Generic;
using Microsoft.Win32;
internal static class Devices {
 internal static List<Common.OutputDevice> Inputs(){var result=new List<Common.OutputDevice>{new Common.OutputDevice{Id="",Label="入力デバイスを選択してください"}};using(var root=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Capture")){if(root!=null)foreach(string id in root.GetSubKeyNames()){try{using(var device=root.OpenSubKey(id)){if(device==null||Convert.ToInt32(device.GetValue("DeviceState",0))!=1)continue;using(var p=device.OpenSubKey("Properties")){if(p==null)continue;string name=Convert.ToString(p.GetValue("{a45c254e-df1c-4efd-8020-67d146a850e0},2","入力"));string hardware=Convert.ToString(p.GetValue("{b3f8fa53-0004-438e-9003-51a46e139bfc},6",""));result.Add(new Common.OutputDevice{Id="{0.0.1.00000000}."+id,Label=name+" ("+hardware+")"});}}}catch{}}}return result;}
 internal static bool ListenEnabled(string id){if(String.IsNullOrEmpty(id))return false;int dot=id.LastIndexOf(".{",StringComparison.Ordinal);Guid endpoint;if(dot<0||!Guid.TryParse(id.Substring(dot+1),out endpoint))return false;using(var key=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Capture\"+endpoint.ToString("B")+@"\Properties")){byte[] value=key==null?null:key.GetValue("{24dbb0fc-9311-4b3d-9cf0-18ff155639d4},1") as byte[];return value!=null&&value.Length>=10&&BitConverter.ToInt16(value,8)!=0;}}
 internal static void SetListen(string root,string id,bool enabled){if(String.IsNullOrEmpty(id))return;using(var p=Process.Start(new ProcessStartInfo(Path.Combine(root,"AudioSettings.exe"),"--set-listen "+id+" "+(enabled?"1":"0")){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(5000)){p.Kill();throw new IOException("音声設定の変更がタイムアウトしました。");}if(p.ExitCode!=0)throw new IOException("入力の「このデバイスを聴く」を変更できませんでした。");}if(ListenEnabled(id)!=enabled)throw new IOException("音声設定を確認できませんでした。");}
 internal static bool Snapshot(string id){string path=Path.Combine(Common.Data,"recovery.json");var record=Common.ReadJson(path);var states=record.ContainsKey("ListenStates")?record["ListenStates"] as Dictionary<string,object>:null;if(states==null)states=new Dictionary<string,object>();if(states.ContainsKey(id))return Convert.ToBoolean(states[id]);bool before=ListenEnabled(id);states[id]=before;Common.WriteJson(path,new{ListenStates=states});return before;}
 internal static void RestoreAll(string root){var record=Common.ReadJson(Path.Combine(Common.Data,"recovery.json"));var states=record.ContainsKey("ListenStates")?record["ListenStates"] as Dictionary<string,object>:null;if(states==null)return;foreach(var item in states){try{SetListen(root,item.Key,Convert.ToBoolean(item.Value));}catch{}}}
 internal static string ProfileKey(Dictionary<string,object> settings){return Common.Text(settings,"InputId","")+"|"+Common.Text(settings,"OutputId","default");}
 internal static double LearnedReserve(Dictionary<string,object> settings){var profiles=settings.ContainsKey("Profiles")?settings["Profiles"] as Dictionary<string,object>:null;return profiles==null?4:Math.Max(4,Math.Min(20,Common.Number(profiles,ProfileKey(settings),4)));}
 internal static void LearnReserve(double reserve){var settings=Common.ReadJson(Path.Combine(Common.Data,"settings.json"));var profiles=settings.ContainsKey("Profiles")?settings["Profiles"] as Dictionary<string,object>:null;if(profiles==null)profiles=new Dictionary<string,object>();profiles[ProfileKey(settings)]=Math.Max(LearnedReserve(settings),reserve);settings["Profiles"]=profiles;Common.WriteJson(Path.Combine(Common.Data,"settings.json"),settings);}
}
